from random import Random
from sympy import Matrix, zeros
from sympy.matrices.normalforms import hermite_normal_form
A = Matrix([[1, 12], [0, 8], [0, 5]])
H = hermite_normal_form(A)
row_hnf = H.T[::-1, ::-1]
assert row_hnf == Matrix([[5, 8, 0], [0, 0, 1]])
print('Issue example:', row_hnf)
rng = Random(0)
for m in range(7):
    for n in range(5):
        for _ in range(8):
            A = Matrix(m, n, [rng.randrange(-3, 4) for _ in range(m*n)])
            H = hermite_normal_form(A)
            assert H.shape == (m, A.rank())
            assert hermite_normal_form(H) == H
            assert A.row_join(H).rank() == A.rank()
            # Unimodular column operations must preserve the HNF.
            if n >= 2:
                B = A.copy()
                B[:, 0] = A[:, 0] + 2*A[:, 1]
                assert hermite_normal_form(B) == H
for m, n in [(0, 0), (0, 3), (4, 0), (5, 2)]:
    assert hermite_normal_form(zeros(m, n)).shape == (m, 0)
print('280 randomized matrices and empty/zero cases passed')
